extended_controls.input_text:
@g = global i16 0, align 2
@byte = global i8 0

declare i16 @produce()
declare void @opaque()
declare i16 @produce_many(i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16, i16)

; A returned call result retains both original bytes through the indirect store.
define i16 @call_result_return(ptr %p) {
  %v = call i16 @produce()
  store volatile i16 %v, ptr %p, align 1
  ret i16 %v
}

; Each atomic word store remains one memory instruction alongside unit arithmetic.
define i16 @atomic_indirect_increment(ptr %p, i16 %v) #0 {
  store atomic i16 %v, ptr %p unordered, align 2
  %r = add i16 %v, 1
  ret i16 %r
}

define i16 @atomic_indirect_decrement(ptr %p, i16 %v) #0 {
  store atomic i16 %v, ptr %p unordered, align 2
  %r = sub i16 %v, 1
  ret i16 %r
}

define i16 @atomic_absolute_decrement(i16 %v) #0 {
  store atomic i16 %v, ptr @g unordered, align 2
  %r = sub i16 %v, 1
  ret i16 %r
}

; Intervening inline assembly can clobber the ABI byte registers.
define void @byte_across_asm(ptr %p, i8 %v) {
  call void asm sideeffect "", "~{a},~{x},~{y}"()
  %w = zext i8 %v to i16
  store volatile i16 %w, ptr %p, align 1
  ret void
}

; A branch permits an intervening call before the byte value reaches the store.
define void @byte_cross_block(ptr %p, i8 %v, i1 %cond) {
  br i1 %cond, label %call, label %store
call:
  call void @opaque()
  br label %store
store:
  %w = zext i8 %v to i16
  store volatile i16 %w, ptr %p, align 1
  ret void
}

; Multiple indirect stores consume the same word alongside a byte-returned step.
define i16 @two_indirect_increment(ptr %p, ptr %q, i16 %v) {
  store volatile i16 %v, ptr %p, align 1
  store volatile i16 %v, ptr %q, align 1
  %r = add i16 %v, 1
  ret i16 %r
}

; A loaded destination pointer retains native materialization and a native store.
define i16 @loaded_pointer_decrement(ptr %pp, i16 %v) {
  %p = load ptr, ptr %pp, align 1
  store volatile i16 %v, ptr %p, align 1
  %r = sub i16 %v, 1
  ret i16 %r
}

; The byte load must precede every destination write when source and destination alias.
define void @byte_volatile_alias(ptr %p) {
  %p1 = getelementptr i8, ptr %p, i16 1
  %v = load volatile i8, ptr %p1, align 1
  %w = zext i8 %v to i16
  store volatile i16 %w, ptr %p, align 1
  ret void
}

; A native consumer of the increment and an original-value return retain word lowering.
define i16 @indirect_increment_return_original(ptr %p, i16 %v) {
  store volatile i16 %v, ptr %p, align 1
  %r = add i16 %v, 1
  store volatile i16 %r, ptr @g, align 2
  ret i16 %v
}

; A nonzero outgoing argument frame is outside the zero-size teardown predicate.
define void @nonzero_call_frame(ptr %p) {
  %v = call i16 @produce_many(i16 1, i16 2, i16 3, i16 4, i16 5, i16 6, i16 7, i16 8, i16 9, i16 10, i16 11, i16 12, i16 13, i16 14, i16 15, i16 16, i16 17, i16 18, i16 19, i16 20)
  store volatile i16 %v, ptr %p, align 1
  ret void
}

attributes #0 = { "target-features"="+mos-a16" }
